import json

import numpy as np
import pytest

from preprocessing import extract_audio, extract_frames, load_wav
from preprocessing.ffmpeg import probe, run_ffmpeg
from preprocessing.pipeline import PreprocessError, preprocess


@pytest.fixture(scope="module")
def sample_video(tmp_path_factory):
    """3 s test pattern with a 440 Hz tone, generated by ffmpeg."""
    path = tmp_path_factory.mktemp("media") / "sample.mp4"
    run_ffmpeg([
        "-f", "lavfi", "-i", "testsrc=size=320x240:rate=10:duration=3",
        "-f", "lavfi", "-i", "sine=frequency=440:duration=3",
        "-shortest", "-pix_fmt", "yuv420p", str(path),
    ])
    return str(path)


def test_probe(sample_video):
    info = probe(sample_video)
    assert info["has_audio"] and info["has_video"]
    assert info["duration_s"] == pytest.approx(3.0, abs=0.2)


def test_extract_audio_is_16k_mono(sample_video, tmp_path):
    wav = extract_audio(sample_video, str(tmp_path / "a.wav"))
    samples, sr = load_wav(wav)
    assert sr == 16_000
    assert samples.ndim == 1
    assert len(samples) / sr == pytest.approx(3.0, abs=0.1)
    assert np.abs(samples).max() > 0.1  # the tone survived


def test_extract_frames_timestamps(sample_video, tmp_path):
    frames = extract_frames(sample_video, str(tmp_path / "frames"), fps=2)
    assert len(frames) == 6
    assert [f["t"] for f in frames] == [0.25, 0.75, 1.25, 1.75, 2.25, 2.75]


def test_default_fps_is_five(sample_video, tmp_path):
    frames = extract_frames(sample_video, str(tmp_path / "frames5"))
    assert len(frames) == 15


def test_preprocess_rejects_silent_video(tmp_path):
    path = tmp_path / "silent.mp4"
    run_ffmpeg(["-f", "lavfi", "-i", "testsrc=size=160x120:rate=5:duration=1",
                "-pix_fmt", "yuv420p", str(path)])
    with pytest.raises(PreprocessError):
        preprocess(str(path), str(tmp_path / "work"))


def test_preprocess_end_to_end(sample_video, tmp_path, monkeypatch):
    fake = {"text": "", "language": "en", "segments": [], "words": []}
    monkeypatch.setattr("preprocessing.pipeline.transcribe", lambda *_a, **_k: fake)
    steps = []
    result = preprocess(sample_video, str(tmp_path / "work"), fps=2, on_step=steps.append)
    assert steps == ["audio", "transcript", "frames"]
    assert result["has_video"] and len(result["frames"]) == 6
    saved = json.loads((tmp_path / "work" / "preprocessed.json").read_text())
    assert saved["duration_s"] == result["duration_s"]
